import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const locales = path.join(root, "src/locales");
const lines = [
  "/**",
  " * Copyright (c) 2023-present Plane Software, Inc. and contributors",
  " * SPDX-License-Identifier: AGPL-3.0-only",
  " * See the LICENSE file for details.",
  " */",
  "// Generated by scripts/generate-locale-loaders.ts. Literal imports must survive package bundling.",
  "export const localeLoaders: Record<string, Record<string, () => Promise<unknown>>> = {",
];
for (const language of fs.readdirSync(locales).sort()) {
  const directory = path.join(locales, language);
  if (!fs.statSync(directory).isDirectory()) continue;
  lines.push(`  ${JSON.stringify(language)}: {`);
  for (const filename of fs.readdirSync(directory).filter((name) => name.endsWith(".json")).sort()) {
    lines.push(`    ${JSON.stringify(filename.slice(0, -5))}: () => import(${JSON.stringify(`../locales/${language}/${filename}`)}),`);
  }
  lines.push("  },");
}
lines.push("};", "");
fs.writeFileSync(path.join(root, "src/core/locale-loaders.generated.ts"), lines.join("\n"));
